<style scoped lang="scss" src="./page-indicator.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";

@Component
export default class PageIndicator extends Vue {
  @Prop({
    type: Number,
    default: 0
  })
  totalPageNumber;

  @Prop({
    type: Number,
    default: 0
  })
  currentPage;
}
</script>

<template>
  <div class="PageIndicator">
    <div
      v-for="i in totalPageNumber"
      :key="i"
      :class="[
        'PageIndicator__Circle',
        i === currentPage ? 'PageIndicator--selected' : ''
      ]"
    ></div>
  </div>
</template>
